import{c as l,$ as s,Q as o,j as i,g as a,o as r,n as d,m as n}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Каталог услуг","description":"Практическое руководство по формированию прейскуранта, расчету нормо-часов, учету накладных расходов цеха и управлению тарифами в ОмниКрафт ЕРП.","frontmatter":{"title":"Каталог услуг","description":"Практическое руководство по формированию прейскуранта, расчету нормо-часов, учету накладных расходов цеха и управлению тарифами в ОмниКрафт ЕРП.","datePublished":"2026-11-15","dateModified":"2026-11-25","order":11},"headers":[],"relativePath":"ru/docs/spaces/services/catalog.md","filePath":"ru/docs/spaces/services/catalog.md","lastUpdated":1795564800000}'),c={name:"ru/docs/spaces/services/catalog.md"},h={id:"каталог-услуг-преискурант-нормо-часы-и-ценообразование",tabindex:"-1"};function p(g,t,m,u,f,x){const e=s("DocIcon");return o(),i("div",null,[a("h1",h,[r(e,{name:"sliders"}),t[0]||(t[0]=d(" Каталог услуг: Прейскурант, нормо-часы и ценообразование ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#каталог-услуг-преискурант-нормо-часы-и-ценообразование","aria-label":'Permalink to "Каталог услуг: Прейскурант, нормо-часы и ценообразование"'},"​",-1))]),t[2]||(t[2]=n('<p>В ремонтной и сервисной деятельности прейскурант выполняет роль главного финансового предохранителя. Если мастер берет расценки «из головы» или годами не пересматривает старые тарифы, мастерская неизбежно попадает в ценовую ловушку: инфляция размывает доходы, аренда и расходники дорожают, а сложные заказы выполняются по цене типовых процедур.</p><p>В <strong>ОмниКрафт ЕРП</strong> каталог услуг — это гибкий инженерный инструмент. Он позволяет разделить регулярный прейскурант на понятные типовые операции с фиксированной ценой и сложные восстановительные процессы, стоимость которых рассчитывается строго от нормативных часов работы мастера и коэффициента накладных расходов цеха.</p><hr><h2 id="две-модели-формирования-сервиснои-стоимости" tabindex="-1">Две модели формирования сервисной стоимости <a class="header-anchor" href="#две-модели-формирования-сервиснои-стоимости" aria-label="Permalink to &quot;Две модели формирования сервисной стоимости&quot;">​</a></h2><p>Программа поддерживает два взаимодополняющих механизма расчета цен. Каждая карточка в реестре помечается визуальным индикатором: <strong>«Фиксированная цена»</strong> или <strong>«По нормо-часам»</strong>.</p><h3 id="_1-фиксированныи-тариф-fixed" tabindex="-1">1. Фиксированный тариф (<code>fixed</code>) <a class="header-anchor" href="#_1-фиксированныи-тариф-fixed" aria-label="Permalink to &quot;1. Фиксированный тариф (`fixed`)&quot;">​</a></h3><p>Применяется для потоковых регламентных процедур с предсказуемой длительностью и неизменным набором действий:</p><ul><li>Первичная диагностика и дефектовка электроники;</li><li>Профилактическая чистка и смазка механического узла;</li><li>Замена внешнего кабеля питания или типового разъема;</li><li>Заточка режущего инструмента или юстировка упоров.</li></ul><p>В этом режиме отпускная стоимость жестко задается в карточке и не зависит от колебаний часовой ставки мастера. Это гарантирует клиенту понятную фиксированную цену «на входе».</p><h3 id="_2-расчетная-стоимость-по-нормо-часам-calculated" tabindex="-1">2. Расчетная стоимость по нормо-часам (<code>calculated</code>) <a class="header-anchor" href="#_2-расчетная-стоимость-по-нормо-часам-calculated" aria-label="Permalink to &quot;2. Расчетная стоимость по нормо-часам (`calculated`)&quot;">​</a></h3><p>Используется для нестандартного ремонта, ювелирной подгонки, реставрации или комплексного восстановления узлов, где ключевой фактор себестоимости — чистое время квалифицированного специалиста.</p><p>Отпускная цена формируется автоматически по формуле:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Формула тарифа</span><div class="formula-heading">Расчет стоимости нормированной услуги</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Итоговая цена</span><span class="math-op">=</span><span class="math-num">(Нормо-часы × Ставка мастера)</span><span class="math-op">×</span><span class="math-num">(1 + Накладные расходы / 100)</span></div></div></div><h4 id="физическии-пример-расчета" tabindex="-1">Физический пример расчета: <a class="header-anchor" href="#физическии-пример-расчета" aria-label="Permalink to &quot;Физический пример расчета:&quot;">​</a></h4><p>Если сложная переборка редуктора требует <code>2,0</code> часа при базовой ставке мастера <code>1 200,00 ₽/ч</code> и нормативе косвенных затрат цеха <code>15%</code>, программа рассчитает отпускную стоимость: <code>(2,0 × 1 200) × 1,15 = 2 760,00 ₽</code>.</p><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Защита маржи через процент накладных расходов</p><p>Никогда не ограничивайте цену только оплатой потраченных часов. Во время ремонта изнашиваются алмазные боры и паяльные жала, расходуются смывки и изолента, потребляется электроэнергия тестовых стендов. Процент накладных расходов автоматически закладывает амортизацию оборудования мастерской в каждый выставленный счет.</p></div><hr><h2 id="сквозная-динамическая-переоценка-через-настроики" tabindex="-1">Сквозная динамическая переоценка через Настройки <a class="header-anchor" href="#сквозная-динамическая-переоценка-через-настроики" aria-label="Permalink to &quot;Сквозная динамическая переоценка через Настройки&quot;">​</a></h2><p>Ключевое преимущество ОмниКрафт ЕРП — отсутствие необходимости вручную перебивать цены десятков позиций при изменении экономической ситуации в мастерской:</p><ol><li>Перейдите во вкладку <strong>«Настройки»</strong>.</li><li>В блоке параметров мастерской укажите актуальную <strong>«Стоимость часа мастера»</strong> (например, увеличив ставку с <code>1 000 ₽</code> до <code>1 200 ₽</code>).</li><li>Сохраните изменения.</li></ol><p>Все услуги с типом ценообразования <em>«Расчетная»</em>, для которых не задана персональная часовая ставка, мгновенно пересчитают свои отпускные цены по новому нормативу. Это позволяет мастерской актуализировать весь прейскурант за 5 секунд.</p><hr><h2 id="пошаговое-руководство-добавление-услуги-в-каталог" tabindex="-1">Пошаговое руководство: Добавление услуги в каталог <a class="header-anchor" href="#пошаговое-руководство-добавление-услуги-в-каталог" aria-label="Permalink to &quot;Пошаговое руководство: Добавление услуги в каталог&quot;">​</a></h2><p>Формирование перечня выполняется во вкладке <strong>«Услуги»</strong>. Интерфейс спроектирован для быстрого наполнения как с клавиатуры, так и на сенсорных экранах.</p><ol><li>Нажмите кнопку <strong>«Добавить услугу»</strong> в правом верхнем углу экрана.</li><li>В открывшемся диалоговом окне заполните параметры: <ul><li><strong>«Название услуги»:</strong> Краткое и однозначное наименование операции, понятное клиенту (<em>«Замена щеточного узла перфоратора»</em>);</li><li><strong>«Примечание»:</strong> Технологический регламент или перечень сопутствующих действий (<em>«Включает снятие корпуса, продувку коллектора и притирку щеток»</em>);</li><li><strong>«Фиксированная цена»:</strong> Сумма по прейскуранту мастерской (при фиксированном тарифе).</li></ul></li><li>Нажмите кнопку <strong>«Сохранить»</strong>.</li></ol><p>Новая позиция сразу появится в общем перечне с указанием стоимости и типа ценообразования.</p><hr><h2 id="управление-каталогом-поиск-правка-и-мягкое-удаление" tabindex="-1">Управление каталогом: Поиск, правка и мягкое удаление <a class="header-anchor" href="#управление-каталогом-поиск-правка-и-мягкое-удаление" aria-label="Permalink to &quot;Управление каталогом: Поиск, правка и мягкое удаление&quot;">​</a></h2><p>По мере развития сервиса перечень операций расширяется до сотен позиций. Для комфортной навигации предусмотрены инструменты быстрого контроля:</p><ul><li><strong>Поиск на лету:</strong> Введите первые буквы названия в строке поиска вверху экрана. Список фильтруется мгновенно. Кнопка с крестиком справа очищает поисковый запрос в одно касание.</li><li>Нажмите карандаш в строке услуги, чтобы изменить название, описание или фиксированную цену.</li><li><strong>Мягкое удаление:</strong> При клике на иконку корзины система запросит подтверждение: <em>«Вы действительно хотите удалить эту услугу?»</em>.</li></ul><div class="info custom-block"><p class="custom-block-title">Что сохраняется после удаления</p><p>Услуга исчезает из действующего каталога. В оформленных заказ-нарядах сохраняются названия и цены строк, записанные при создании.</p></div><hr><h2 id="интеграция-каталога-в-сквозные-цепочки-мастерскои" tabindex="-1">Интеграция каталога в сквозные цепочки мастерской <a class="header-anchor" href="#интеграция-каталога-в-сквозные-цепочки-мастерскои" aria-label="Permalink to &quot;Интеграция каталога в сквозные цепочки мастерской&quot;">​</a></h2><p>Каталог услуг в ОмниКрафт ЕРП тесно интегрирован со всеми контурами программы:</p><ul><li><strong>Рабочий стол заказ-нарядов:</strong> При приеме инструмента в ремонт мастер выбирает нужные манипуляции прямо из каталога. Норма времени и расценка подтягиваются автоматически.</li><li><strong>Онлайн-витрина:</strong> Перечень открытых услуг можно опубликовать на персональном сайте мастерской, предоставив клиентам прозрачный веб-прейскурант без звонков и уточнений.</li><li><strong>Аналитика доходности:</strong> Система отслеживает объемы оказанных услуг, позволяя мастеру видеть, какие направления сервиса приносят основной чистый доход, а какие являются низкомаржинальными.</li></ul><hr><h2 id="справочная-матрица-полеи-карточки-услуги" tabindex="-1">Справочная матрица полей карточки услуги <a class="header-anchor" href="#справочная-матрица-полеи-карточки-услуги" aria-label="Permalink to &quot;Справочная матрица полей карточки услуги&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Поле ввода</th><th style="text-align:left;">Назначение параметра</th><th style="text-align:left;">Влияние на расчет</th><th style="text-align:left;">Рекомендация мастера</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Название услуги</strong></td><td style="text-align:left;">Идентификатор в чеках и нарядах</td><td style="text-align:left;">Выводится в заказ-наряде и акте клиенту</td><td style="text-align:left;">Формулируйте кратко, без сложного заводского сленга</td></tr><tr><td style="text-align:left;"><strong>Примечание</strong></td><td style="text-align:left;">Описание состава и этапов работ</td><td style="text-align:left;">Пояснение для мастера и заказчика</td><td style="text-align:left;">Фиксируйте технологические границы (что входит в цену)</td></tr><tr><td style="text-align:left;"><strong>Фиксированная цена</strong></td><td style="text-align:left;">Прямая стоимость операции</td><td style="text-align:left;">Базовая сумма в наряде (режим «Фиксированная»)</td><td style="text-align:left;">Применяйте для потоковых регламентных процедур</td></tr><tr><td style="text-align:left;"><strong>Нормо-часы</strong></td><td style="text-align:left;">Трудоемкость операции в часах</td><td style="text-align:left;">Умножается на ставку мастера (режим «Расчетная»)</td><td style="text-align:left;">Оценивайте чистое рабочее время квалифицированного мастера</td></tr><tr><td style="text-align:left;"><strong>Накладные расходы</strong></td><td style="text-align:left;">Процент покрытия общецеховых затрат</td><td style="text-align:left;">Увеличивает себестоимость труда</td><td style="text-align:left;">Закладывайте 10–25% на износ оснастки и коммунальные платежи</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Цеховой совет мастера: Проводите ревизию каталога раз в квартал</p><p>Не держите в активном списке позиции, которые клиенты заказывали единожды два года назад. Архивируйте устаревшие операции и ежеквартально сопоставляйте нормативные нормо-часы с фактическим хронометражем на рабочем месте. Если сложная процедура стабильно занимает 2,5 часа вместо заложенных 1,5 — своевременно обновите норматив, чтобы не работать в убыток.</p></div><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если итоговая стоимость услуги не меняется при редактировании нормо-часов?</summary><div class="faq-content"><p>Проверьте режим ценообразования в карточке услуги: если активен переключатель «Фиксированная цена», программа игнорирует трудоемкость и часовую ставку. Переключите режим на «Расчетная», чтобы стоимость вычислялась автоматически по формуле.</p></div></details><details class="faq-item"><summary class="faq-summary">Можно ли удалить услугу, которая есть в старом наряде?</summary><div class="faq-content"><p>Да. После подтверждения услуга исчезнет из каталога. Ранее записанные строки наряда сохранятся.</p></div></details><details class="faq-item"><summary class="faq-summary">Как изменить часовую ставку сразу для всех расчетных услуг сервиса?</summary><div class="faq-content"><p>Перейдите в глобальные настройки пространства на вкладку «Настройки» и обновите базовую ставку нормо-часа мастера. Все расчетные услуги в каталоге и новые заказ-наряды автоматически применят обновленный тариф.</p></div></details></div>',42))])}const q=l(c,[["render",p]]);export{y as __pageData,q as default};
